SELECT * FROM schedule_shifts
WHERE shift_date BETWEEN #{startDate} AND #{endDate}
ORDER BY worker_id, job_id, shift_date

SELECT * FROM schedule_shifts
WHERE worker_id = #{workerId} AND shift_date BETWEEN #{startDate} AND #{endDate}
ORDER BY shift_date, start_time

SELECT * FROM schedule_shifts
WHERE application_id = #{applicationId}
ORDER BY shift_date, start_time
